            color: var(--accent);
            margin-bottom: 0.25rem;
        }

        .grid {
            display: grid;
            grid-template-columns: 1fr;
            gap: 1.25rem;
            width: 100%;
        }

        @media (min-width: 850px) {
            .grid {
                grid-template-columns: 1fr 1fr;
                gap: 2rem;
            }
            body {
                padding: 2rem;
            }
        }

        .card {
            background: var(--card-bg);
            border-radius: 12px;
            padding: 1.25rem;
            box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
            border: 1px solid var(--border-color);
            width: 100%;
            overflow: hidden;
        }

        .card-title {
            font-size: 1.15rem;
            margin-bottom: 1rem;
            font-weight: 600;
            display: flex;
            justify-content: space-between;
            align-items: center;
            flex-wrap: wrap;
            gap: 0.5rem;
        }

        .form-group {
            margin-bottom: 1rem;
        }

