            background: #fff;
            border: 1px solid #bee3f8;
            border-radius: 6px;
            resize: none;
        }
    </style>
</head>
<body>

<div class="container">
    <header>
        <h1>Roommate Bill Board</h1>
        <p style="color: var(--text-muted); font-size: 0.9rem;">Track utility dates, uneven payments, and clear final balances.</p>
    </header>

    <div class="grid">
        <div>
            <div class="card">
                <div class="card-title">Roommates</div>
                <div class="roommate-tag-container" id="roommatesList"></div>
                <div style="display: flex; gap: 0.5rem;">
                    <input type="text" id="newRoommateInput" placeholder="Add name...">
                    <button style="width: auto;" onclick="addRoommate()">Add</button>
                </div>
            </div>

            <div class="card" id="formCard">
                <div class="card-title" id="formTitle">Add New Bill</div>
                <input type="hidden" id="editBillId" value="">

                <div class="form-group">
                    <label for="billName">Bill Name</label>
                    <input type="text" id="billName" placeholder="e.g., Gas, Trash, Water">
                </div>
                <div class="form-group">
                    <label for="billTotal">Total Amount ($)</label>
                    <input type="number" id="billTotal" step="0.01" placeholder="0.00">
                </div>
                <div class="form-group">
                    <label for="billDue">Due Date</label>
                    <input type="date" id="billDue">
                </div>
                <div class="form-group">
                    <label for="billPayer">Who paid upfront?</label>
                    <select id="billPayer"></select>
                </div>
                <div style="display: flex; gap: 0.5rem;">
                    <button id="submitBillBtn" onclick="handleFormSubmit()">Add to Board</button>
                    <button id="cancelEditBtn" class="btn-secondary" style="display:none;" onclick="cancelEditing()">Cancel</button>
                </div>
            </div>
        </div>

        <div>
            <div class="card" style="background: #ebf4ff; border-color: #bee3f8;">
                <div class="card-title" style="color: #2b6cb0; margin-bottom: 0.25rem;">
                    <span>Net Settlement Board</span>
                    <button id="copySummaryBtn" class="btn-small" onclick="copyShareableSummary()">📋 Copy Summary</button>
                </div>
                <p style="font-size: 0.8rem; color: #4a5568; margin-bottom: 0.75rem;">Fewest payment transfers needed to square up.</p>

                <div id="balancesDisplay"></div>

                <div class="preview-box-container" id="previewContainer">
                    <label style="color: #2b6cb0; font-size: 0.75rem; margin-bottom: 0.2rem;">Select and copy the text box below:</label>
                    <textarea class="preview-box" id="summaryPreviewText" readonly onclick="this.select()"></textarea>
                </div>
            </div>

            <div class="card">
                <div class="card-title">Active Bills & Progress</div>
                <div id="billsContainer"></div>
            </div>
        </div>
    </div>
</div>

<script>
    let roommates = JSON.parse(localStorage.getItem('bb_roommates')) || ['Alex', 'Taylor', 'Jordan'];
    let bills = JSON.parse(localStorage.getItem('bb_bills')) || [
        {
            id: 1,
            name: 'Electric Bill',
            total: 150.00,
            dueDate: new Date().toISOString().split('T')[0],
            payer: 'Alex',
            partialPayments: { 'Taylor': 20.00, 'Jordan': 0 },
            history: ["Bill initialized. Base share: $50.00"]
        }
    ];

    let finalSettlementText = ""; 

    function init() {
        renderRoommates();
        updatePayerDropdown();
        renderBills();
        calculateBalances();
    }

    function saveState() {
        localStorage.setItem('bb_roommates', JSON.stringify(roommates));
        localStorage.setItem('bb_bills', JSON.stringify(bills));
    }

    function renderRoommates() {
        const container = document.getElementById('roommatesList');
        container.innerHTML = '';
        roommates.forEach(name => {
            const tag = document.createElement('div');
            tag.className = 'roommate-tag';
            tag.innerHTML = `${name} <button onclick="removeRoommate('${name}')">&times;</button>`;
            container.appendChild(tag);
        });
        updatePayerDropdown();
    }

    function updatePayerDropdown() {
        const select = document.getElementById('billPayer');
        const currentSelection = select.value;
        select.innerHTML = '';
        roommates.forEach(name => {
            const opt = document.createElement('option');
            opt.value = name;
            opt.textContent = name;
            select.appendChild(opt);
        });
        if (roommates.includes(currentSelection)) select.value = currentSelection;
    }

    function addRoommate() {
        const input = document.getElementById('newRoommateInput');
        const name = input.value.trim();
        if (name && !roommates.includes(name)) {
            roommates.push(name);
            input.value = '';
            bills.forEach(bill => {
                if (!(name in bill.partialPayments)) bill.partialPayments[name] = 0;
                bill.history.push(`Added ${name} to tracking loop.`);
            });
            saveState();
            renderRoommates();
            renderBills();
            calculateBalances();
        }
    }

    function removeRoommate(name) {
        roommates = roommates.filter(r => r !== name);
        bills.forEach(bill => {
            delete bill.partialPayments[name];
            if (bill.payer === name) bill.payer = roommates[0] || '';
            bill.history.push(`Removed ${name} from metrics.`);
        });
        saveState();
        renderRoommates();
        renderBills();
        calculateBalances();
    }

    function getStatusLabelAndClass(bill) {
        const splitCount = roommates.length;
        if (splitCount <= 1) return { label: 'Settled', class: 'status-paid' };

        const share = bill.total / splitCount;
        let totalCollectedFromOthers = 0;
        let expectedFromOthers = share * (splitCount - 1);

        roommates.forEach(rm => {
            if (rm !== bill.payer) totalCollectedFromOthers += (bill.partialPayments[rm] || 0);
        });

        if (totalCollectedFromOthers >= expectedFromOthers - 0.02) {
            return { label: 'Fully Paid', class: 'status-paid' };
        }
        if (!bill.dueDate) return { label: 'Pending', class: 'status-pending' };

        const today = new Date();
        today.setHours(0,0,0,0);
        const dueDate = new Date(bill.dueDate + 'T00:00:00');
        const diffDays = Math.ceil((dueDate - today) / (1000 * 60 * 60 * 24));

        if (diffDays < 0) return { label: 'Overdue', class: 'status-overdue' };
        if (diffDays <= 3) return { label: 'Due Soon', class: 'status-soon' };
        return { label: 'Pending', class: 'status-pending' };
    }

    function renderBills() {
        const container = document.getElementById('billsContainer');
        container.innerHTML = '';

        if (bills.length === 0) {
            container.innerHTML = '<p style="color: var(--text-muted); font-size: 0.9rem;">No active bills on the board.</p>';
            return;
        }

        bills.forEach(bill => {
            const splitCount = roommates.length;
            const targetPerPerson = splitCount > 0 ? (bill.total / splitCount) : 0;
            const statusObj = getStatusLabelAndClass(bill);

            const billEl = document.createElement('div');
            billEl.className = 'bill-item';

            let venmoRowsHtml = '';
            roommates.forEach(rm => {
                if (rm !== bill.payer) {
                    const dynamicPaid = bill.partialPayments[rm] || 0;
                    const remaining = Math.max(0, targetPerPerson - dynamicPaid);

                    venmoRowsHtml += `
                        <div class="venmo-row">
                            <span>${rm} (Owes $${targetPerPerson.toFixed(2)})</span>
                            <div class="venmo-input-wrapper">
                                <label style="display:inline;">Paid:</label>
                                <input type="number" class="venmo-input" step="0.01" value="${dynamicPaid}" 
                                    oninput="updatePartialPayment(${bill.id}, '${rm}', this.value)"
                                    onblur="updatePartialPayment(${bill.id}, '${rm}', this.value)">
                                <span style="font-size: 0.75rem; margin-left: 2px; color: ${remaining <= 0.01 ? 'var(--success)' : 'var(--text-muted)'}; font-weight:${remaining <= 0.01 ? '600':'400'}">
                                    ${remaining <= 0.01 ? '✓ Done' : '$' + remaining.toFixed(2) + ' left'}
                                </span>
                            </div>
                        </div>
                    `;
                }
            });

            let historyEntries = (bill.history || []).map(h => `<div class="history-entry">• ${h}</div>`).join('');

            billEl.innerHTML = `
                <div class="bill-header">
                    <span class="bill-name">${bill.name} <span class="status-badge ${statusObj.class}">${statusObj.label}</span></span>
                    <span style="font-weight: 600;">$${bill.total.toFixed(2)}</span>
                </div>
                <div class="bill-meta">
                    Paid upfront by <strong>${bill.payer}</strong> | Due: ${bill.dueDate || 'Unscheduled'}
                </div>
                <div class="venmo-tracking">
                    ${venmoRowsHtml || '<div style="font-size:0.8rem; color:var(--text-muted);">Add roommates to calculate.</div>'}
                </div>
                <div class="history-log">
                    ${historyEntries || 'No logs recorded.'}
                </div>
                <div class="bill-actions">
                    <button class="action-btn" onclick="startEditing(${bill.id})">Edit</button>
                    <button class="action-btn delete" onclick="deleteBill(${bill.id})">Remove</button>
                </div>
            `;
            container.appendChild(billEl);
        });
    }

    function handleFormSubmit() {
        const idField = document.getElementById('editBillId').value;
        const name = document.getElementById('billName').value.trim();
        const total = parseFloat(document.getElementById('billTotal').value);
        const dueDate = document.getElementById('billDue').value;
        const payer = document.getElementById('billPayer').value;

        if (!name || isNaN(total) || !payer) {
            alert('Please complete all configuration inputs.');
            return;
        }

        if (idField) {
            const bill = bills.find(b => b.id == idField);
            if (bill) {
                bill.name = name;
                bill.total = total;
                bill.dueDate = dueDate;
                if (!bill.history) bill.history = [];
                bill.history.push(`Modified details on ${new Date().toLocaleDateString()}: $${total} total.`);

                if (bill.payer !== payer) {
                    bill.payer = payer;
                    delete bill.partialPayments[payer];
                    bill.history.push(`Payer shifted to ${payer}.`);
                }
                roommates.forEach(rm => {
                    if (rm !== bill.payer && !(rm in bill.partialPayments)) bill.partialPayments[rm] = 0;
                });
            }
        } else {
            const partialPayments = {};
            roommates.forEach(rm => { if (rm !== payer) partialPayments[rm] = 0; });

            bills.push({
                id: Date.now(),
                name,
                total,
                dueDate,
                payer,
                partialPayments,
                history: [`Bill registered by ${payer} on ${new Date().toLocaleDateString()}`]
            });
        }

        cancelEditing();
        saveState();
        renderBills();
        calculateBalances();
    }

    function startEditing(billId) {
        const bill = bills.find(b => b.id === billId);
        if (!bill) return;

        document.getElementById('editBillId').value = bill.id;
        document.getElementById('billName').value = bill.name;
        document.getElementById('billTotal').value = bill.total;
        document.getElementById('billDue').value = bill.dueDate;
        document.getElementById('billPayer').value = bill.payer;

        document.getElementById('formTitle').textContent = "Edit Bill Metrics";
        document.getElementById('submitBillBtn').textContent = "Save Changes";
        document.getElementById('cancelEditBtn').style.display = "inline-block";
        document.getElementById('formCard').style.borderColor = "var(--accent)";

        window.scrollTo({ top: 0, behavior: 'smooth' });
    }

    function cancelEditing() {
        document.getElementById('editBillId').value = "";
        document.getElementById('billName').value = "";
        document.getElementById('billTotal').value = "";
        document.getElementById('billDue').value = "";
        document.getElementById('formTitle').textContent = "Add New Bill";
        document.getElementById('submitBillBtn').textContent = "Add to Board";
        document.getElementById('cancelEditBtn').style.display = "none";
        document.getElementById('formCard').style.borderColor = "var(--border-color)";
    }

    function updatePartialPayment(billId, roommate, amount) {
        const bill = bills.find(b => b.id === billId);
        if (bill) {
            const parsedAmount = parseFloat(amount) || 0;

            if (bill.partialPayments[roommate] !== parsedAmount) {
                const timeString = new Date().toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
                if (!bill.history) bill.history = [];
                bill.history.push(`${roommate} updated Venmo: $${parsedAmount.toFixed(2)} (${timeString})`);

                bill.partialPayments[roommate] = parsedAmount;
                saveState();

                const activeId = document.activeElement ? document.activeElement.id : null;
                const selectionStart = document.activeElement ? document.activeElement.selectionStart : null;
                const selectionEnd = document.activeElement ? document.activeElement.selectionEnd : null;

                renderBills();
                calculateBalances();

                if (activeId) {
                    const el = document.getElementById(activeId);
                    if (el) {
                        el.focus();
                        if (selectionStart !== null && selectionEnd !== null) {
                            el.setSelectionRange(selectionStart, selectionEnd);
                        }
                    }
                }
            }
        }
    }

    function deleteBill(billId) {
        bills = bills.filter(b => b.id !== billId);
        if (document.getElementById('editBillId').value == billId) cancelEditing();
        saveState();
        renderBills();
        calculateBalances();
    }

    function calculateBalances() {
        const balancesDisplay = document.getElementById('balancesDisplay');
        balancesDisplay.innerHTML = '';

        if (roommates.length === 0) {
            balancesDisplay.innerHTML = '<p>Define roommates to process balances.</p>';
            return;
        }

        let debts = {};
        roommates.forEach(r1 => {
            debts[r1] = {};
            roommates.forEach(r2 => { debts[r1][r2] = 0; });
        });

        bills.forEach(bill => {
            const splitCount = roommates.length;
            if (splitCount <= 1) return;
            const share = bill.total / splitCount;
            const payer = bill.payer;

            roommates.forEach(rm => {
                if (rm !== payer) {
                    const partial = bill.partialPayments[rm] || 0;
                    const netOwed = share - partial;
                    if (netOwed > 0) debts[rm][payer] += netOwed;
                    else if (netOwed < 0) debts[payer][rm] += Math.abs(netOwed);
                }
            });
        });

        let netPositions = {};
        roommates.forEach(rm => {
            let incoming = 0;
            let outgoing = 0;
            roommates.forEach(other => {
                incoming += debts[other][rm];
                outgoing += debts[rm][other];
            });
            netPositions[rm] = incoming - outgoing;
        });

        let summaryHtml = '';
        let textSettlementLines = [];
        let localOwer = [...roommates].filter(r => netPositions[r] < -0.01);
        let localReceiver = [...roommates].filter(r => netPositions[r] > 0.01);

        localOwer.sort((a,b) => netPositions[a] - netPositions[b]);
        localReceiver.sort((a,b) => netPositions[b] - netPositions[a]);

        let i = 0, j = 0;
        while (i < localOwer.length && j < localReceiver.length) {
            let ower = localOwer[i];
            let receiver = localReceiver[j];
            let settlementAmount = Math.min(Math.abs(netPositions[ower]), netPositions[receiver]);

            if (settlementAmount > 0.01) {
                summaryHtml += `
                    <div class="summary-row">
                        <span><strong>${ower}</strong> pays <strong>${receiver}</strong></span>
                        <span class="owes-amount">$${settlementAmount.toFixed(2)}</span>
                    </div>
                `;
                textSettlementLines.push(`- ${ower} pays ${receiver}: $${settlementAmount.toFixed(2)}`);
            }

            netPositions[ower] += settlementAmount;
            netPositions[receiver] -= settlementAmount;
            if (Math.abs(netPositions[ower]) < 0.01) i++;
            if (Math.abs(netPositions[receiver]) < 0.01) j++;
        }

        if (!summaryHtml) {
            summaryHtml = '<div class="summary-row" style="color:var(--success); font-weight:600;">✓ Every account is completely squared!</div>';
            textSettlementLines.push("Everything is completely squared away!");
        }

        balancesDisplay.innerHTML = summaryHtml;
        buildTextSummary(textSettlementLines);
    }

    function buildTextSummary(settlementLines) {
        let text = `📋 ROOMMATE UTILITY SUMMARY\nGenerated: ${new Date().toLocaleDateString()}\n\n`;
        text += `--- BILLS STATUS ---\n`;

        if (bills.length === 0) {
            text += "No active bills.\n";
        } else {
            bills.forEach(b => {
                const status = getStatusLabelAndClass(b).label;
                text += `• ${b.name}: $${b.total.toFixed(2)} (${b.payer}) | [${status}] | Due: ${b.dueDate || 'N/A'}\n`;

                let partials = [];
                roommates.forEach(rm => {
                    if (rm !== b.payer && b.partialPayments[rm] > 0) {
                        partials.push(`${rm}: $${b.partialPayments[rm].toFixed(2)}`);
                    }
                });
                if (partials.length > 0) {
                    text += `  (Paid: ${partials.join(', ')})\n`;
                }
            });
        }

        text += `\n--- SETTLEMENT DIRECTIVES ---\n`;
        text += settlementLines.join('\n');

        finalSettlementText = text;
        document.getElementById('summaryPreviewText').value = text;
    }

    function copyShareableSummary() {
        const previewContainer = document.getElementById('previewContainer');

        navigator.clipboard.writeText(finalSettlementText).then(() => {
            const btn = document.getElementById('copySummaryBtn');
            const originalText = btn.textContent;
            btn.textContent = "✓ Copied!";
            btn.style.backgroundColor = "var(--success)";
            btn.style.color = "white";

            setTimeout(() => {
                btn.textContent = originalText;
                btn.style.backgroundColor = "";
                btn.style.color = "";
            }, 2000);
        }).catch(err => {
            previewContainer.style.display = "block";
            document.getElementById('summaryPreviewText').select();
        });
    }

    init();
</script>

</body>
</html>
